interface Props {
  a?: number;
  b?: string;
}

const obj1: Props = { a: 5 }; // Valid, 'b' is optional

// We enforce that ALL properties must be present
const obj2: Required<Props> = { a: 5 }; // ERROR: Property 'b' is missing!

const obj3: Required<Props> = { a: 5, b: "hello" }; // Valid!
